CREATE FUNCTION hr.fn_GetDirectReports ( @ManagerID BIGINT, @TenantID BIGINT ) RETURNS TABLE AS RETURN ( SELECT em.EmployeeID, e.EmployeeCode, e.FirstName + ' ' + e.LastName AS EmployeeFullName, e.PersonalEmail, e.[Status], em.EffectiveFrom FROM hr.EmployeeManager em INNER JOIN hr.Employee e ON em.EmployeeID = e.EmployeeID WHERE em.ManagerID = @ManagerID AND em.TenantID = @TenantID AND em.IsDeleted = 0 AND (em.EffectiveTo IS NULL OR em.EffectiveTo >= CAST(GETUTCDATE() AS DATE)) );